import{text,list,identifiers,choice}from'../creative-kit/state.js?v=0.13.0';
export const ROUTES={context:'Separate contexts',sequence:'Sequence the approaches',invent:'Invent a third mechanism'};export const SIDE_FIELDS=['proposal','benefit','context','cost','evidence'];export const PLAN_FIELDS=['title','mechanism','boundary','cost','test','learn'];
export const proposal=()=>({proposal:'',benefit:'',context:'',cost:'',evidence:''});
export const plan=(id,route)=>({id,route,title:ROUTES[route],mechanism:'',boundary:'',cost:'',test:'',learn:'',protects:[],stale:false});
export function make(id='first',example='example'){const w={id,problem:example==='blank'?'':'Should routine battery decisions be automated or approved by a person?',sides:{a:proposal(),b:proposal()},plans:Object.keys(ROUTES).map((r,i)=>plan(`p${i+1}`,r)),selected:null};if(example!=='blank'){w.sides.a={proposal:'Automate routine decisions within a written envelope.',benefit:'Respond quickly and consistently.',context:'The inputs are timely, limits are explicit and exceptions are detectable.',cost:'Unrecognised cases may pass through without human attention.',evidence:'Which past decisions were predictable and within clear limits?'};w.sides.b={proposal:'Require a person to approve each decision.',benefit:'Preserve judgment and accountability when context matters.',context:'Consequences are hard to reverse or information is ambiguous.',cost:'Waiting can erase useful opportunities and burden the approver.',evidence:'Which past interventions caught a material issue?'};w.plans[0]={...w.plans[0],mechanism:'Automate cases that satisfy an explicit envelope; route ambiguous cases to an owner.',boundary:'Define observable conditions for leaving the envelope.',protects:['a','b'],test:'Replay a fictional week and classify each decision before seeing its outcome.',learn:'If cases cannot be classified consistently, improve the envelope before automating.'};}return w;}
export function validate(w){if(!w.sides||!w.sides.a||!w.sides.b)throw Error('Both proposals are required.');for(const s of Object.values(w.sides))SIDE_FIELDS.forEach(f=>text(s[f]));list(w.plans,9);identifiers(w.plans);for(const p of w.plans){choice(p.route,Object.keys(ROUTES));PLAN_FIELDS.forEach(f=>text(p[f]));list(p.protects,2);if(new Set(p.protects).size!==p.protects.length||p.protects.some(s=>!['a','b'].includes(s))||typeof p.stale!=='boolean')throw Error('Invalid protected benefits.');}if(w.selected!==null&&!w.plans.some(p=>p.id===w.selected))throw Error('Selected proposal is missing.');return w;}
export function apply(w,a){if(a.type==='edit'){if(a.collection==='sides'){choice(a.item,['a','b']);choice(a.field,SIDE_FIELDS);w.sides[a.item][a.field]=text(a.value);w.plans.filter(p=>p.protects.includes(a.item)).forEach(p=>p.stale=true);}else{const p=w.plans.find(p=>p.id===a.item);if(!p)throw Error('Adaptation is missing.');choice(a.field,PLAN_FIELDS);p[a.field]=text(a.value);}}else if(a.type==='protect'){const p=w.plans.find(p=>p.id===a.id);if(!p)throw Error('Adaptation is missing.');choice(a.side,['a','b']);if(!p.protects.includes(a.side))p.protects.push(a.side);}else if(a.type==='unprotect'){const p=w.plans.find(p=>p.id===a.id);if(!p)throw Error('Adaptation is missing.');p.protects=p.protects.filter(s=>s!==a.side);}else if(a.type==='review'){const p=w.plans.find(p=>p.id===a.id);if(!p)throw Error('Adaptation is missing.');p.stale=false;}else if(a.type==='fork'){const p=w.plans.find(p=>p.id===a.parent);if(!p)throw Error('Adaptation is missing.');w.plans.push({...structuredClone(p),id:a.id,title:p.title+' · variation'});}else if(a.type==='select'){if(!w.plans.some(p=>p.id===a.id))throw Error('Adaptation is missing.');w.selected=w.selected===a.id?null:a.id;}else if(a.type==='remove'){w.plans=w.plans.filter(p=>p.id!==a.id);if(w.selected===a.id)w.selected=null;}else throw Error('Unknown disagreement action.');}
export function markdown(w){return['# Productive disagreement','',w.problem,'',...Object.entries(w.sides).flatMap(([key,s])=>[`## Proposal ${key.toUpperCase()}`,'',...SIDE_FIELDS.flatMap(f=>[`**${f}**`,s[f]||'_Not written._',''])]),...w.plans.flatMap(p=>[`## ${p.title}${w.selected===p.id?' · selected for a test':''}${p.stale?' · benefit changed, recheck':''}`,'',`Route: ${ROUTES[p.route]}`,`Aims to protect: ${p.protects.map(s=>w.sides[s].benefit).join(' + ')||'No benefit linked yet'}`,'',...PLAN_FIELDS.slice(1).flatMap(f=>[`**${f}**`,p[f]||'_Not written._',''])])].join('\n');}
